package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class DailyReportSupplementInputTest {
 boolean mysql(){return false;}
 DailyReportInputComponentTest h;LocalDate day;Instant cutoff;
 void setup()throws Exception{h=new DailyReportInputComponentTest(){@Override boolean mysql(){return DailyReportSupplementInputTest.this.mysql();}};h.nativeSetup("agent");day=h.data.nativeData().fixture().day();cutoff=h.data.nativeData().cutoff().plusSeconds(23).plusNanos(1000);}
 @Test void ActualWholeNewCutoffPreservesOriginalCatalogueBodyAndFreezesGenerationTwo()throws Exception{setup();var value=h.service.captureSupplement(day,cutoff);assertNotNull(value);assertEquals(cutoff,value.cutoff());assertTrue(value.sourceProof().complete());assertEquals(1,value.sourceProof().candidates().size());assertEquals(1,value.dependencies().size());assertEquals(1,value.referenceTargetsByEvidence().size());assertSame(value,h.rr(()->h.service.verifyObserved(value)));var command=new GenerationFlowService.Prepare("report:daily:"+day,2,GenerationFlowService.Stage.DAILY_REPORT,day,null,value.dependencies(),List.of(),value.sourceProof().verifiedDependencyIds(),true,"a".repeat(64));var frozen=new ReportInputSnapshotService((c,t)->value.sourceProof()).freeze(command,cutoff);assertEquals("complete",frozen.coverageState());assertTrue(frozen.hasContent());assertEquals(CanonicalJson.parse(h.data.nativeData().completed().bodyJson()),CanonicalJson.parse(frozen.snapshotJson()).get("members").get(0).get("body"));assertEquals(2,h.data.nativeData().fixture().f().sends);}
 @Test void CurrentBlockedBodyRemainsExcludedOriginalAndRejectsTheOldNewCutoffProof()throws Exception{setup();var old=h.service.captureSupplement(day,cutoff);h.data.nativeData().fixture().f().jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",h.data.nativeData().completed().version().contentId());assertThrows(RuntimeException.class,()->h.rr(()->h.service.verifyObserved(old)));var fresh=h.service.captureSupplement(day,cutoff);assertTrue(fresh.sourceProof().candidates().getFirst().evidence().blocked());assertEquals(old.sourceProof().candidates().getFirst().evidence().bodyJson(),fresh.sourceProof().candidates().getFirst().evidence().bodyJson());assertTrue(fresh.sourceProof().noUpdateDates().isEmpty());assertSame(fresh,h.rr(()->h.service.verifyObserved(fresh)));}
 @Test void MissingNativePostcommitOriginalCannotBorrowCurrentBodyOrInventNoUpdate()throws Exception{setup();h.data.nativeData().fixture().f().jdbc.update("DELETE FROM jobs WHERE target_type='content_availability'");var value=h.service.captureSupplement(day,cutoff);assertNotNull(value);assertEquals(1,value.sourceProof().candidates().size());assertNull(value.sourceProof().candidates().getFirst().evidence());var command=new GenerationFlowService.Prepare("report:daily:"+day,2,GenerationFlowService.Stage.DAILY_REPORT,day,null,value.dependencies(),List.of(),value.sourceProof().verifiedDependencyIds(),true,"a".repeat(64));var frozen=new ReportInputSnapshotService((c,t)->value.sourceProof()).freeze(command,cutoff);assertFalse(frozen.hasContent());assertTrue(CanonicalJson.parse(frozen.snapshotJson()).get("members").isEmpty());assertFalse(CanonicalJson.parse(frozen.snapshotJson()).get(com.lianxibu.site.service.content.ReportInputProfile.FIELD).get("coverage").get("missing_inputs").isEmpty());assertTrue(value.sourceProof().noUpdateDates().isEmpty());assertTrue(value.dependencies().isEmpty());assertTrue(value.referenceTargetsByEvidence().isEmpty());assertEquals(2,h.data.nativeData().fixture().f().sends);}
 @Test void InitialFiveClockAndExplicitWholeBudgetIssuerAndTransactionsRemainBounded()throws Exception{setup();var value=h.service.captureSupplement(day,cutoff);assertThrows(RuntimeException.class,()->h.service.capture(day,cutoff));assertThrows(RuntimeException.class,()->h.service.captureSupplement(day,h.data.nativeData().cutoff().minusNanos(1000)));assertThrows(RuntimeException.class,()->h.service.captureSupplement(day,cutoff.plusNanos(1)));assertThrows(RuntimeException.class,()->h.create(1024).captureSupplement(day,cutoff));assertThrows(RuntimeException.class,()->h.rr(()->h.create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES).verifyObserved(value)));assertThrows(RuntimeException.class,()->h.rr(()->h.service.captureSupplement(day,cutoff)));assertThrows(RuntimeException.class,()->h.service.verifyObserved(value));}
}
